        .back-btn:hover { background-color: var(--bg-hover); }

        .header-title h1 {
            font-size: 15px;
            font-weight: 600;
            color: var(--text-primary);
        }
        .header-title p {
            font-size: 11px;
            color: var(--text-secondary);
            margin-top: 2px;
        }

        .header-right {
            display: flex;
            align-items: center;
            gap: 10px;
        }

        .nav-pill {
            padding: 6px 16px;
            border-radius: 20px;
            font-size: 13px;
            font-weight: 500;
            cursor: pointer;
            border: none;
            transition: all 0.2s;
        }
        .nav-pill.active {
            background-color: var(--text-primary);
            color: var(--bg-panel);
        }
        .nav-pill.inactive {
            background-color: transparent;
            color: var(--text-secondary);
        }
        .nav-pill.inactive:hover {
            color: var(--text-primary);
            background-color: rgba(255,255,255,0.05);
        }

        .theme-toggle {
            width: 32px;
            height: 32px;
            border-radius: 50%;
            border: none;
            background: transparent;
            color: var(--text-secondary);
            cursor: pointer;
            display: flex;
            align-items: center;
            justify-content: center;
        }

        /* --- Main Layout --- */
        main {
            display: flex;
            flex: 1;
            overflow: hidden;
            position: relative;
        }

        /* --- Canvas Area (Left) --- */
        .canvas-area {
            flex: 1;
            position: relative;
            overflow: hidden;
            background-color: var(--bg-app); /* Slightly darker than panel */
            display: flex;
            flex-direction: column;
        }

        .canvas-hint {
            position: absolute;
            top: 16px;
            left: 50%;
            transform: translateX(-50%);
            background-color: rgba(0,0,0,0.5);
            padding: 6px 16px;
            border-radius: 20px;
            font-size: 11px;
            color: var(--text-secondary);
            pointer-events: none;
            z-index: 5;
            white-space: nowrap;
        }

        /* The Flowsheet Container - Intact Sheet */
