        /* Zone Styles */
        .zone-title {
            font-size: 24px;
            text-transform: uppercase;
            letter-spacing: 2px;
            color: #555;
            font-weight: 700;
            margin-bottom: 30px;
            padding-left: 10px;
        }

        .process-diagram {
            position: relative;
            height: 300px;
            width: 100%;
